import { API_BASE_URL } from '../config/api';

export interface Track {
  id: string;
  title: string;
  artist: string;
  album: string;
  durationSeconds: number;
  artworkUrl: string;
}

export async function fetchPlaylist(): Promise<Track[]> {
  const response = await fetch(`${API_BASE_URL}/library/playlists/liked`);
  if (!response.ok) throw new Error(`Library failed with status ${response.status}`);
  return (await response.json()) as Track[];
}

import { useCallback, useEffect, useMemo, useState } from 'react';
import { View, Text, TouchableOpacity, FlatList, Image, StyleSheet, SafeAreaView, ActivityIndicator } from 'react-native';
import { fetchPlaylist, type Track } from '../services/library';

const colors = {
  accent: '#f05039',
  bg: '#0f120e',
  danger: '#ff6b5e',
  borderAlt: '#2a2f2a',
  text: '#f5f5f0',
  muted: '#8a8f8a',
  border: '#242a24',
  surface: '#1a1f1a',
}

const format = (seconds: number): string => {
  const m = Math.floor(seconds / 60);
  const s = seconds % 60;
  return `${m}:${String(s).padStart(2, '0')}`;
};

export function PlayerScreen(): JSX.Element {
  const [tracks, setTracks] = useState<Track[]>([]);
  const [index, setIndex] = useState(0);
  const [position, setPosition] = useState(0);
  const [playing, setPlaying] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

    const load = useCallback(async () => {

    try {
      const data = await fetchPlaylist();
      setTracks(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load the library.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void load();
  }, [load]);

  useEffect(() => {
    if (!playing || tracks.length === 0) return undefined;
    const id = setInterval(() => {
      setPosition(prev => {
        const track = tracks[index];
        if (track && prev + 1 >= track.durationSeconds) {
          setIndex(i => (i + 1) % tracks.length);
          return 0;
        }
        return prev + 1;
      });
    }, 1000);
    return () => clearInterval(id);
  }, [playing, tracks, index]);

  const track = tracks[index];
  const progress = track ? position / track.durationSeconds : 0;

  const seek = useCallback((ratio: number) => {
    if (track) setPosition(Math.round(ratio * track.durationSeconds));
  }, [track]);

  const renderItem = useCallback(({ item }: { item: Track }) => (
    <TouchableOpacity
      style={[styles.row, item.id === track?.id && styles.rowActive]}
      onPress={() => { setIndex(tracks.indexOf(item)); setPosition(0); setPlaying(true); }}
      accessibilityRole="button"
      accessibilityLabel={`Play ${item.title} by ${item.artist}`}
    >
      <Text style={styles.rowTitle} numberOfLines={1}>{item.title}</Text>
      <Text style={styles.rowArtist}>{item.artist}</Text>
    </TouchableOpacity>
  ), [track, tracks]);

  return (
    <SafeAreaView style={styles.safe}>
      {loading && <ActivityIndicator color="{colors.accent}" style={styles.center} />}
      {!loading && error && <Text style={styles.error}>{error}</Text>}
      {!loading && track && (
        <>
          <View style={styles.nowPlaying}>
            <Image source={{ uri: track.artworkUrl }} style={styles.art} accessibilityLabel={`${track.album} artwork`} />
            <Text style={styles.title} numberOfLines={1}>{track.title}</Text>
            <Text style={styles.artist}>{track.artist}</Text>
            <View style={styles.seekRow}>
              <Text style={styles.time}>{format(position)}</Text>
              <TouchableOpacity
                style={styles.seek}
                onPress={e => seek(e.nativeEvent.locationX / 260)}
                accessibilityRole="adjustable"
                accessibilityLabel="Seek"
              >
                <View style={[styles.seekFill, { width: `${progress * 100}%` }]} />
              </TouchableOpacity>
              <Text style={styles.time}>{format(track.durationSeconds)}</Text>
            </View>
            <View style={styles.controls}>
              <TouchableOpacity onPress={() => setIndex(i => (i - 1 + tracks.length) % tracks.length)} accessibilityRole="button" accessibilityLabel="Previous">
                <Text style={styles.ctrl}>⏮</Text>
              </TouchableOpacity>
              <TouchableOpacity onPress={() => setPlaying(p => !p)} accessibilityRole="button" accessibilityLabel={playing ? 'Pause' : 'Play'}>
                <Text style={[styles.ctrl, styles.ctrlBig]}>{playing ? '⏸' : '▶'}</Text>
              </TouchableOpacity>
              <TouchableOpacity onPress={() => { setIndex(i => (i + 1) % tracks.length); setPosition(0); }} accessibilityRole="button" accessibilityLabel="Next">
                <Text style={styles.ctrl}>⏭</Text>
              </TouchableOpacity>
            </View>
          </View>
          <FlatList data={tracks} renderItem={renderItem} keyExtractor={t => t.id} style={styles.list} />
        </>
      )}
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  safe: { flex: 1, backgroundColor: colors.bg },
  center: { marginTop: 40 },
  error: { color: colors.danger, textAlign: 'center', marginTop: 24 },
  nowPlaying: { alignItems: 'center', padding: 20 },
  art: { width: 200, height: 200, borderRadius: 12, backgroundColor: colors.borderAlt },
  title: { color: colors.text, fontSize: 20, fontWeight: '700', marginTop: 16 },
  artist: { color: colors.muted, marginTop: 4 },
  seekRow: { flexDirection: 'row', alignItems: 'center', gap: 10, marginTop: 20, width: 260 },
  seek: { flex: 1, height: 4, borderRadius: 2, backgroundColor: colors.borderAlt, overflow: 'hidden' },
  seekFill: { height: 4, backgroundColor: colors.accent },
  time: { color: colors.muted, fontSize: 11, fontVariant: ['tabular-nums'] },
  controls: { flexDirection: 'row', alignItems: 'center', gap: 32, marginTop: 20 },
  ctrl: { color: colors.text, fontSize: 28 },
  ctrlBig: { fontSize: 40, color: colors.accent },
  list: { flex: 1 },
  row: { padding: 14, borderBottomWidth: 1, borderBottomColor: colors.border },
  rowActive: { backgroundColor: colors.surface },
  rowTitle: { color: colors.text, fontWeight: '600' },
  rowArtist: { color: colors.muted, fontSize: 12, marginTop: 2 },
});
